package agent

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"time"

	"golang.org/x/term"
)

// EventType represents a normalized lifecycle event from any agent.
// Agents translate their native hooks into these event types via ParseHookEvent.
type EventType int

const (
	// SessionStart indicates the agent session has begun.
	SessionStart EventType = iota + 1

	// TurnStart indicates the user submitted a prompt and the agent is about to work.
	TurnStart

	// TurnEnd indicates the agent finished responding to a prompt.
	TurnEnd

	// Compaction indicates the agent is about to compress its context window.
	// This triggers the same save logic as TurnEnd but also resets the transcript offset.
	Compaction

	// SessionEnd indicates the session has been terminated.
	SessionEnd

	// SubagentStart indicates a subagent (task) has been spawned.
	SubagentStart

	// SubagentEnd indicates a subagent (task) has completed.
	SubagentEnd

	// ModelUpdate indicates the agent reported the LLM model being used.
	// This fires on hooks that carry model info but have no other lifecycle action
	// (e.g., Gemini CLI's BeforeModel). The framework stores the model as a hint
	// for subsequent TurnStart/TurnEnd events in the same session.
	ModelUpdate

	// ToolUse indicates the agent ran a tool that touched files mid-turn.
	// Carries ModifiedFiles/NewFiles/DeletedFiles so the framework can populate
	// state.FilesTouched incrementally — without this, agents like Codex that
	// commit mid-turn (before TurnEnd fires) have no per-tool file accounting,
	// and the carry-forward path falls back to whole-transcript extraction.
	ToolUse
)

// String returns a human-readable name for the event type.
func (e EventType) String() string {
	switch e {
	case SessionStart:
		return "SessionStart"
	case TurnStart:
		return "TurnStart"
	case TurnEnd:
		return "TurnEnd"
	case Compaction:
		return "Compaction"
	case SessionEnd:
		return "SessionEnd"
	case SubagentStart:
		return "SubagentStart"
	case SubagentEnd:
		return "SubagentEnd"
	case ModelUpdate:
		return "ModelUpdate"
	case ToolUse:
		return "ToolUse"
	default:
		return "Unknown"
	}
}

// Event is a normalized lifecycle event produced by an agent's ParseHookEvent method.
// The framework dispatcher uses these events to drive checkpoint/session lifecycle actions.
type Event struct {
	// Type is the kind of lifecycle event.
	Type EventType

	// SessionID identifies the agent session.
	SessionID string

	// PreviousSessionID is non-empty when this event represents a session continuation
	// or handoff (e.g., Claude starting a new session ID after exiting plan mode).
	PreviousSessionID string

	// SessionRef is an agent-specific reference to the transcript (typically a file path).
	SessionRef string

	// Prompt is the user's prompt text (populated on TurnStart events).
	Prompt string

	// Model is the LLM model identifier (e.g., "claude-sonnet-4-20250514").
	// Populated on SessionStart (Claude Code), ModelUpdate (Gemini CLI BeforeModel),
	// and TurnStart/TurnEnd events when the agent provides model info.
	Model string

	// Timestamp is when the event occurred.
	Timestamp time.Time

	// ToolUseID identifies the tool invocation (for SubagentStart/SubagentEnd events).
	ToolUseID string

	// SubagentID identifies the subagent instance (for SubagentEnd events).
	SubagentID string

	// SubagentTranscriptPath is the agent-declared path to the subagent's own
	// transcript (SubagentEnd). Set it whenever the hook payload names the file;
	// Codex and Cursor both send agent_transcript_path.
	//
	// When empty the framework probes the layout Claude Code and Factory AI Droid
	// share (cli.ResolveAgentTranscriptPath). For any other agent that probe finds
	// nothing and yields "" silently, so the only symptom is a task checkpoint with
	// no subagent transcript plus file extraction falling back to the main
	// transcript — where a subagent's edits never appear. Declaring the path is how
	// an agent opts out of that guess.
	SubagentTranscriptPath string

	// ToolInput is the raw tool input JSON (for subagent type/description extraction).
	// Used when both SubagentType and TaskDescription are empty (agents that don't provide
	// these fields directly parse them from ToolInput).
	ToolInput json.RawMessage

	// SubagentType is the kind of subagent (for SubagentStart/SubagentEnd events).
	// Used with TaskDescription instead of ToolInput
	SubagentType    string
	TaskDescription string

	// ModifiedFiles is the list of file paths modified by a subagent (SubagentEnd)
	// or a tool call (ToolUse). Paths may be absolute, cwd-relative, or
	// repo-relative; lifecycle handlers normalize against the worktree root.
	ModifiedFiles []string

	// NewFiles and DeletedFiles carry create/delete paths for ToolUse events,
	// kept separate from ModifiedFiles so consumers can reason about agent intent.
	NewFiles     []string
	DeletedFiles []string

	// CWD is the working directory the agent was running in when the event fired.
	// Set on ToolUse so cwd-relative payload paths can be resolved before
	// repo-root normalization.
	CWD string

	// ResponseMessage is an optional message to display to the user via the agent.
	ResponseMessage string

	// Hook-provided session metrics (populated by agents that report these via hooks).
	DurationMs        int64 // Session duration from agent hook (e.g., Cursor SessionEnd)
	TurnCount         int   // Number of agent turns/loops (e.g., Cursor Stop hook)
	ContextTokens     int   // Context window tokens used (e.g., Cursor PreCompact hook)
	ContextWindowSize int   // Total context window size (e.g., Cursor PreCompact hook)

	// TokenUsage carries per-turn token accounting reported by an agent hook
	// directly (e.g., Cursor's Stop hook). Set when the hook payload contains
	// authoritative token data that the JSONL transcript does not. Lifecycle
	// handlers prefer this over transcript-based calculation when populated.
	TokenUsage *TokenUsage

	// SkillEvents records native agent skill signals surfaced by hooks.
	// The lifecycle layer persists these to session state and later checkpoint metadata.
	SkillEvents []SkillEvent

	// Metadata holds agent-specific state that the framework stores and makes available
	// on subsequent events. Examples: Pi's activeLeafId, Cursor's is_background_agent.
	Metadata map[string]string
}

// ReadAndParseHookInput decodes a single JSON hook payload from stdin into the
// given type. This is a shared helper for agent ParseHookEvent implementations.
//
// It deliberately does NOT use io.ReadAll, which waits for stdin to reach EOF.
// Agents drive hooks by piping a JSON payload to the hook process, but some
// keep the write end of that pipe open for the hook's lifetime rather than
// closing it after writing — notably on Windows/Git Bash, where a full payload
// arrives but EOF never does. io.ReadAll then blocked indefinitely and the hook
// (e.g. gemini session-start) hung forever (issue #1398). A streaming
// json.Decoder returns as soon as one complete JSON value has been read,
// independent of when — or whether — stdin is closed.
func ReadAndParseHookInput[T any](stdin io.Reader) (*T, error) {
	raw, err := ReadHookInputRaw(stdin)
	if err != nil {
		return nil, err
	}
	var result T
	if err := json.Unmarshal(raw, &result); err != nil {
		return nil, fmt.Errorf("failed to parse hook input: %w", err)
	}
	return &result, nil
}

// ReadHookInputRaw returns the raw bytes of a single JSON hook payload read from
// stdin, without waiting for EOF. It is the shared primitive behind every
// agent's hook-input read (issue #1398); callers that need custom parsing
// (e.g. key-name fallbacks, or forwarding the bytes to a subprocess) use this
// directly, while the common case uses ReadAndParseHookInput.
func ReadHookInputRaw(stdin io.Reader) (json.RawMessage, error) {
	return ReadHookInputRawLimited(stdin, -1)
}

// ReadHookInputRawLimited is ReadHookInputRaw with a ceiling of limit bytes on
// the JSON value (limit < 0 means unlimited). It is used at the external/plugin
// boundary to bound an untrusted payload — without reintroducing the EOF-wait
// hang, since the streaming decoder still returns on the first complete value.
func ReadHookInputRawLimited(stdin io.Reader, limit int64) (json.RawMessage, error) {
	// If stdin is an interactive terminal there is no payload coming at all: the
	// command was run by hand, or the agent left the console attached instead of
	// wiring up a pipe. Decoding would block waiting for input that never comes,
	// so treat it as empty and return promptly.
	if StdinLooksInteractive(stdin) {
		return nil, errors.New("empty hook input")
	}

	r := stdin
	if limit >= 0 {
		r = io.LimitReader(stdin, limit)
	}
	var raw json.RawMessage
	if err := json.NewDecoder(r).Decode(&raw); err != nil {
		if errors.Is(err, io.EOF) {
			return nil, errors.New("empty hook input")
		}
		return nil, fmt.Errorf("failed to parse hook input: %w", err)
	}
	return raw, nil
}

// StdinLooksInteractive reports whether r is an interactive terminal, i.e. no
// piped hook payload is on its way. Hook readers use it to bail out promptly
// instead of blocking on a read that will never complete (issue #1398).
func StdinLooksInteractive(r io.Reader) bool {
	f, ok := r.(*os.File)
	return ok && term.IsTerminal(int(f.Fd())) //nolint:gosec // G115: uintptr->int is safe for fd
}

//go:build integration

package integration

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/stretchr/testify/require"
)

// TestCodexSubagent_StoresDeclaredSubagentTranscript drives Codex's subagent hooks
// end to end — subagent-start → the subagent edits a file → subagent-stop — and
// asserts the task checkpoint stores the subagent's own rollout.
//
// The rollout path here is deliberately flat, matching Codex's real layout and
// matching neither candidate the Claude Code fallback probes, so the assertion can
// only pass if the declared path is honoured (see Event.SubagentTranscriptPath).
func TestCodexSubagent_StoresDeclaredSubagentTranscript(t *testing.T) {
	t.Parallel()
	env := NewFeatureBranchEnv(t)

	const (
		sessionID  = "test-codex-subagent"
		agentID    = "child-thread-9"
		editedFile = "docs/red.md"
	)

	require.NoError(t, env.WriteSessionState(sessionID, &session.State{
		SessionID:  sessionID,
		AgentType:  agent.AgentTypeCodex,
		BaseCommit: env.GetHeadHash(),
	}))

	rolloutDir := filepath.Join(env.RepoDir, ".entire", "tmp", "codex-rollouts")
	require.NoError(t, os.MkdirAll(rolloutDir, 0o750))
	parentRollout := filepath.Join(rolloutDir, "rollout-"+sessionID+".jsonl")
	require.NoError(t, os.WriteFile(parentRollout, []byte(`{"type":"session_meta","payload":{"id":"`+sessionID+`"}}`+"\n"), 0o600))
	subagentRollout := filepath.Join(rolloutDir, "rollout-"+agentID+".jsonl")
	require.NoError(t, os.WriteFile(subagentRollout,
		[]byte(`{"type":"response_item","payload":{"content":"wrote `+editedFile+`"}}`+"\n"), 0o600))

	hook := codexHooker(t, env.RepoDir, sessionID, parentRollout)
	hook("subagent-start", map[string]any{
		"hook_event_name": "SubagentStart",
		"agent_id":        agentID,
		"agent_type":      "reviewer",
		"turn_id":         "turn-1",
	})

	env.WriteFile(editedFile, "Red is a warm colour.\n")

	hook("subagent-stop", map[string]any{
		"hook_event_name":       "SubagentStop",
		"agent_id":              agentID,
		"agent_type":            "reviewer",
		"agent_transcript_path": subagentRollout,
		"stop_hook_active":      false,
		"turn_id":               "turn-1",
	})

	// Codex sends no tool_use_id, so agent_id is the correlation key and therefore
	// names the task directory.
	wantPath := paths.EntireMetadataDir + "/" + sessionID +
		"/tasks/" + agentID + "/" + paths.AgentTranscriptFileName(agentID)
	content, ok := env.ReadFileFromBranch(env.GetShadowBranchName(), wantPath)
	require.True(t, ok,
		"subagent transcript not stored at %s — the declared agent_transcript_path was not honoured", wantPath)
	require.Contains(t, content, editedFile, "stored transcript is not the subagent's rollout")
}

package cursor

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// intFromJSON safely converts a json.Number to int64, returning 0 for
// empty or non-numeric values (hook payloads may omit optional fields).
func intFromJSON(n json.Number) int64 {
	v, err := n.Int64()
	if err != nil {
		return 0
	}
	return v
}

// ParseHookEvent translates a Cursor hook into a normalized lifecycle Event.
// Returns nil if the hook has no lifecycle significance.
func (c *CursorAgent) ParseHookEvent(ctx context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
	switch hookName {
	case HookNameSessionStart:
		return c.parseSessionStart(stdin)
	case HookNameBeforeSubmitPrompt:
		return c.parseTurnStart(ctx, stdin)
	case HookNameStop:
		return c.parseTurnEnd(ctx, stdin)
	case HookNameSessionEnd:
		return c.parseSessionEnd(ctx, stdin)
	case HookNamePreCompact:
		return c.parsePreCompact(stdin)
	case HookNameSubagentStart:
		return c.parseSubagentStart(stdin)
	case HookNameSubagentStop:
		return c.parseSubagentStop(stdin)
	default:
		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
	}
}

// ReadTranscript reads the raw JSONL transcript bytes for a session.
func (c *CursorAgent) ReadTranscript(sessionRef string) ([]byte, error) {
	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
	if err != nil {
		return nil, fmt.Errorf("failed to read transcript: %w", err)
	}
	return data, nil
}

// --- Internal hook parsing functions ---

// resolveTranscriptRef returns the transcript path from the hook input, or computes
// it dynamically when the hook doesn't provide one (Cursor CLI pattern).
func (c *CursorAgent) resolveTranscriptRef(ctx context.Context, conversationID, rawPath string) string {
	if rawPath != "" {
		return rawPath
	}

	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		logging.Warn(ctx, "cursor: failed to get worktree root for transcript resolution", "err", err)
		return ""
	}

	sessionDir, err := c.GetSessionDir(repoRoot)
	if err != nil {
		logging.Warn(ctx, "cursor: failed to get session dir for transcript resolution", "err", err)
		return ""
	}

	return c.ResolveSessionFile(sessionDir, conversationID)
}

func (c *CursorAgent) parseSessionStart(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[sessionStartRaw](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.SessionStart,
		SessionID:  raw.ConversationID,
		SessionRef: raw.TranscriptPath,
		Model:      raw.Model,
		Timestamp:  time.Now(),
	}, nil
}

func (c *CursorAgent) parseTurnStart(ctx context.Context, stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[beforeSubmitPromptInputRaw](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.TurnStart,
		SessionID:  raw.ConversationID,
		SessionRef: c.resolveTranscriptRef(ctx, raw.ConversationID, raw.TranscriptPath),
		Prompt:     raw.Prompt,
		Model:      raw.Model,
		Timestamp:  time.Now(),
	}, nil
}

func (c *CursorAgent) parseTurnEnd(ctx context.Context, stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[stopHookInputRaw](stdin)
	if err != nil {
		return nil, err
	}
	event := &agent.Event{
		Type:       agent.TurnEnd,
		SessionID:  raw.ConversationID,
		SessionRef: c.resolveTranscriptRef(ctx, raw.ConversationID, raw.TranscriptPath),
		Model:      raw.Model,
		TurnCount:  int(intFromJSON(raw.LoopCount)),
		Timestamp:  time.Now(),
	}
	event.TokenUsage = tokenUsageFromStop(raw)
	return event, nil
}

// tokenUsageFromStop converts the per-turn token fields in Cursor's stop hook
// payload into the framework-wide TokenUsage struct. Cursor reports
// input_tokens as the *total* input (cache_read + cache_write + fresh), so we
// derive the fresh-input portion here. Returns nil when no usable token fields
// are present (some Cursor versions / hook variants omit them entirely),
// signaling "no data" rather than "all zeros".
func tokenUsageFromStop(raw *stopHookInputRaw) *agent.TokenUsage {
	totalInput := int(intFromJSON(raw.InputTokens))
	output := int(intFromJSON(raw.OutputTokens))
	if totalInput == 0 && output == 0 {
		return nil
	}
	cacheRead := int(intFromJSON(raw.CacheReadTokens))
	cacheWrite := int(intFromJSON(raw.CacheWriteTokens))
	freshInput := totalInput - cacheRead - cacheWrite
	if freshInput < 0 {
		freshInput = 0
	}
	return &agent.TokenUsage{
		InputTokens:         freshInput,
		CacheCreationTokens: cacheWrite,
		CacheReadTokens:     cacheRead,
		OutputTokens:        output,
		APICallCount:        1,
	}
}

func (c *CursorAgent) parseSessionEnd(ctx context.Context, stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[sessionEndRaw](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.SessionEnd,
		SessionID:  raw.ConversationID,
		SessionRef: c.resolveTranscriptRef(ctx, raw.ConversationID, raw.TranscriptPath),
		Model:      raw.Model,
		DurationMs: intFromJSON(raw.DurationMs),
		Timestamp:  time.Now(),
	}, nil
}

func (c *CursorAgent) parsePreCompact(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[preCompactHookInputRaw](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:              agent.Compaction,
		SessionID:         raw.ConversationID,
		SessionRef:        raw.TranscriptPath,
		ContextTokens:     int(intFromJSON(raw.ContextTokens)),
		ContextWindowSize: int(intFromJSON(raw.ContextWindowSize)),
		Timestamp:         time.Now(),
	}, nil
}

func (c *CursorAgent) parseSubagentStart(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[subagentStartHookInputRaw](stdin)
	if err != nil {
		return nil, err
	}
	if raw.Task == "" {
		return nil, nil //nolint:nilnil // nil event = no lifecycle action
	}
	return &agent.Event{
		Type:            agent.SubagentStart,
		SessionID:       raw.ConversationID,
		SessionRef:      raw.TranscriptPath,
		SubagentID:      raw.SubagentID,
		ToolUseID:       raw.SubagentID,
		SubagentType:    raw.SubagentType,
		TaskDescription: raw.Task,
		Timestamp:       time.Now(),
	}, nil
}

func (c *CursorAgent) parseSubagentStop(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[subagentStopHookInputRaw](stdin)
	if err != nil {
		return nil, err
	}
	if raw.Task == "" {
		return nil, nil //nolint:nilnil // nil event = no lifecycle action
	}
	event := &agent.Event{
		Type:            agent.SubagentEnd,
		SessionID:       raw.ConversationID,
		SessionRef:      raw.TranscriptPath,
		ToolUseID:       raw.SubagentID,
		SubagentType:    raw.SubagentType,
		TaskDescription: raw.Task,
		Timestamp:       time.Now(),
		SubagentID:      raw.SubagentID,
		ModifiedFiles:   raw.ModifiedFiles,
		// Cursor names the subagent's transcript in the payload. This field was
		// parsed but never forwarded, so the framework fell back to guessing Claude
		// Code's layout — which does not exist under Cursor's session dir, so the
		// task checkpoint stored no subagent transcript at all.
		SubagentTranscriptPath: raw.AgentTranscriptPath,
	}
	return event, nil
}

