	if err != nil {
		return nil, false
	}
	var file HooksFile
	if err := json.Unmarshal(data, &file); err != nil {
		return nil, false
	}
	var events []string
	add := func(label string, groups []MatcherGroup) {
		for _, g := range groups {
			if len(g.Hooks) > 0 {
				events = append(events, label)
				return
			}
		}
	}
