// cpID as its most recent condensation. Ownership is what makes an
// Entire-Checkpoint trailer resolvable, and it survives across commits:
// condenseAndUpdateState stores the ID in LastCheckpointID so a later amend can
// restore the same trailer. So a session owning cpID means the checkpoint
// exists, whether it was written by this commit or the one being amended.
func anySessionOwnsCheckpoint(sessions []*SessionState, cpID id.CheckpointID) bool {
	for _, state := range sessions {
		if state.LastCheckpointID == cpID {
			return true
		}
	}
	return false
}

// warnDanglingCheckpointTrailer reports a commit carrying an Entire-Checkpoint
// trailer that no session owns: the checkpoint it names was never written, so
// `entire explain` on this commit resolves to nothing. That is the end state of
// every trailer/condense divergence — PrepareCommitMsg stamped a session it
// judged eligible and PostCommit then declined to condense it — and it is
// invisible without this line, because both halves individually look like
// routine skips.
//
// Two cases reach "no session condensed" without the trailer being dangling,
// and both are excluded by the caller rather than here:
//
//   - Amend. handleAmendCommitMsg preserves or restores the trailer, and a
//     message-only amend has no new content to condense. Covered by seeding
//     from LastCheckpointID, which the original commit set.
//   - Cherry-pick, revert, and rebase replay. The trailer rides along from the
//     source commit, whose session may not exist in this worktree at all, so
//     ownership cannot be established locally. Covered by the isRebase guard.
//
// Without those two exclusions this fires on ordinary git usage, which is worse
// than not warning at all: WARN is the level `entire doctor` surfaces, so a
// routinely-firing line trains people to ignore the one that matters.
func warnDanglingCheckpointTrailer(logCtx context.Context, checkpointID id.CheckpointID, sessions []*SessionState) {
	phases := make([]string, 0, len(sessions))
	totalTaskRecords := 0
	for _, state := range sessions {
		phases = append(phases, string(state.Phase))
		totalTaskRecords += len(state.TaskRecords)
	}
	logging.Warn(logCtx, "post-commit: trailer left dangling, no session condensed into it",
		slog.String("strategy", "manual-commit"),
		slog.String("checkpoint_id", checkpointID.String()),
		slog.Int("sessions", len(sessions)),
		slog.Any("session_phases", phases),
		slog.Int("task_records", totalTaskRecords),
	)
}

