// danglingTrailerLogMessage is the log message warnDanglingCheckpointTrailer
// emits. Asserting on the log is the only way to observe it: it deliberately
// has no return value and no state side effect, because its entire purpose is
// to be greppable in .entire/logs and visible to `entire doctor`.
const danglingTrailerLogMessage = "trailer left dangling, no session condensed into it"

// TestPostCommit_DanglingCheckpointTrailerWarning covers the one shape that
// warrants the warning and the three that must not trigger it. The two
// exclusions are what make it usable: an amend and a cherry-pick both reach
// "no session condensed" while their checkpoint exists, so warning on them
// would fire on ordinary git usage and train people to ignore the level
// `entire doctor` reports.
func TestPostCommit_DanglingCheckpointTrailerWarning(t *testing.T) {
	const trailerID = "f6a1b2c3d4e5"

	tests := []struct {
		name string
		// phase the session is in when the trailered commit lands.
		phase session.Phase
		// noNewContent pins the transcript baseline to what the shadow branch
		// already holds, so condensation finds nothing to do — the state that
		// leaves a stamped trailer unfilled.
		noNewContent bool
		// ownsTrailer presets LastCheckpointID to the committed trailer, which
		// is what an amend looks like: the trailer is inherited and the
		// checkpoint was written by the commit being amended.
		ownsTrailer bool
		// sequenceOp simulates rebase/cherry-pick/revert via .git/rebase-merge.
		sequenceOp bool
		wantWarn   bool
	}{
		{
			name:         "idle session with nothing to condense warns",
			phase:        session.PhaseIdle,
			noNewContent: true,
			wantWarn:     true,
		},
		{
			name:         "amend does not warn: the session already owns the checkpoint",
			phase:        session.PhaseIdle,
			noNewContent: true,
			ownsTrailer:  true,
		},
		{
			name:         "sequence operation does not warn: ownership is not local",
			phase:        session.PhaseIdle,
			noNewContent: true,
			sequenceOp:   true,
		},
		{
			name:  "active session that condenses does not warn",
			phase: session.PhaseActive,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			dir := setupGitRepo(t)
			t.Chdir(dir)

			repo, err := git.PlainOpen(dir)
			require.NoError(t, err)

			s := &ManualCommitStrategy{}
			sessionID := "test-dangling-trailer"
			setupSessionWithCheckpoint(t, s, repo, dir, sessionID)

			state, err := s.loadSessionState(context.Background(), sessionID)
			require.NoError(t, err)
			state.Phase = tt.phase
			if tt.noNewContent {
				state.LastInteractionTime = nil
				state.CheckpointTranscriptStart = 2
				state.CheckpointTranscriptSize = shadowTranscriptSize(t, repo, state)
			}
			if tt.ownsTrailer {
				state.LastCheckpointID = id.MustCheckpointID(trailerID)
			}
			require.NoError(t, s.saveSessionState(context.Background(), state))

			if tt.sequenceOp {
				require.NoError(t, os.MkdirAll(filepath.Join(dir, ".git", "rebase-merge"), 0o750))
			}

			commitWithCheckpointTrailer(t, repo, dir, trailerID)

			logs := captureStrategyLogs(t, func(ctx context.Context) {
				require.NoError(t, s.PostCommit(ctx))
			})

			if tt.wantWarn {
				assert.Contains(t, logs, danglingTrailerLogMessage,
					"expected the dangling-trailer warning")
				assert.Contains(t, logs, `"level":"WARN"`,
					"the dangling-trailer line must be WARN, the level doctor surfaces")
				return
			}
			assert.NotContains(t, logs, danglingTrailerLogMessage,
				"the trailer resolves to a real checkpoint here; warning would be a false positive")
		})
	}
}

// captureStrategyLogs runs fn with a real Logger writing to a temp directory and
// returns everything it emitted. A real Logger rather than a fake handler keeps
// the assertion honest about level, since that is half of what is under test.
func captureStrategyLogs(t *testing.T, fn func(ctx context.Context)) string {
	t.Helper()

	logDir := t.TempDir()
	logger, err := logging.New(logging.Config{Dir: logDir, Level: slog.LevelDebug})
	require.NoError(t, err)

	fn(logging.WithLogger(context.Background(), logger))
	require.NoError(t, logger.Close())

	content, err := os.ReadFile(filepath.Join(logDir, "entire.log"))
	if errors.Is(err, os.ErrNotExist) {
		return ""
	}
	require.NoError(t, err)
	return string(content)
}

// assertSingleWarning is a readability guard: a warning that fires more than
// once per commit is as bad as one that fires wrongly.
func countOccurrences(haystack, needle string) int {
	return strings.Count(haystack, needle)
}
